CREATE TYPE "ResourceKind" AS ENUM ('URL', 'DOCUMENT');
CREATE TYPE "AnalysisStatus" AS ENUM ('SUCCESS', 'FAILED', 'MANUAL');
CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT, "name" TEXT, "googleId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Resource" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "kind" "ResourceKind" NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "url" TEXT, "normalizedUrl" TEXT, "resourceType" TEXT NOT NULL DEFAULT 'Other', "sourcePlatform" TEXT, "summary" TEXT, "author" TEXT, "thumbnailUrl" TEXT, "faviconUrl" TEXT, "contentHash" TEXT, "language" TEXT, "isAITool" BOOLEAN NOT NULL DEFAULT false, "isFavorite" BOOLEAN NOT NULL DEFAULT false, "archivedAt" TIMESTAMP(3), "lastAnalyzedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Resource_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Category" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "Category_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Tag" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, CONSTRAINT "Tag_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ResourceCategory" ("resourceId" TEXT NOT NULL, "categoryId" TEXT NOT NULL, CONSTRAINT "ResourceCategory_pkey" PRIMARY KEY ("resourceId","categoryId"));
CREATE TABLE "ResourceTag" ("resourceId" TEXT NOT NULL, "tagId" TEXT NOT NULL, CONSTRAINT "ResourceTag_pkey" PRIMARY KEY ("resourceId","tagId"));
CREATE TABLE "DocumentMetadata" ("id" TEXT NOT NULL, "resourceId" TEXT NOT NULL, "cloudinaryPublicId" TEXT NOT NULL, "secureUrl" TEXT NOT NULL, "originalFilename" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "size" INTEGER NOT NULL, "uploadedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "DocumentMetadata_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AIAnalysis" ("id" TEXT NOT NULL, "resourceId" TEXT NOT NULL, "provider" TEXT, "model" TEXT, "primaryProvider" TEXT, "fallbackProvider" TEXT, "status" "AnalysisStatus" NOT NULL, "sourceType" TEXT NOT NULL, "schemaVersion" TEXT NOT NULL DEFAULT '1', "result" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AIAnalysis_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE UNIQUE INDEX "User_googleId_key" ON "User"("googleId"); CREATE UNIQUE INDEX "Category_name_key" ON "Category"("name"); CREATE UNIQUE INDEX "Tag_name_key" ON "Tag"("name"); CREATE UNIQUE INDEX "DocumentMetadata_resourceId_key" ON "DocumentMetadata"("resourceId"); CREATE UNIQUE INDEX "AIAnalysis_resourceId_key" ON "AIAnalysis"("resourceId"); CREATE UNIQUE INDEX "Resource_userId_normalizedUrl_key" ON "Resource"("userId","normalizedUrl");
CREATE INDEX "Resource_userId_createdAt_idx" ON "Resource"("userId","createdAt"); CREATE INDEX "Resource_userId_normalizedUrl_idx" ON "Resource"("userId","normalizedUrl"); CREATE INDEX "Resource_userId_isFavorite_idx" ON "Resource"("userId","isFavorite"); CREATE INDEX "Resource_userId_archivedAt_idx" ON "Resource"("userId","archivedAt"); CREATE INDEX "Resource_userId_resourceType_idx" ON "Resource"("userId","resourceType"); CREATE INDEX "ResourceCategory_categoryId_idx" ON "ResourceCategory"("categoryId"); CREATE INDEX "ResourceTag_tagId_idx" ON "ResourceTag"("tagId");
ALTER TABLE "Resource" ADD CONSTRAINT "Resource_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ResourceCategory" ADD CONSTRAINT "ResourceCategory_resourceId_fkey" FOREIGN KEY ("resourceId") REFERENCES "Resource"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ResourceCategory" ADD CONSTRAINT "ResourceCategory_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "Category"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ResourceTag" ADD CONSTRAINT "ResourceTag_resourceId_fkey" FOREIGN KEY ("resourceId") REFERENCES "Resource"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ResourceTag" ADD CONSTRAINT "ResourceTag_tagId_fkey" FOREIGN KEY ("tagId") REFERENCES "Tag"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "DocumentMetadata" ADD CONSTRAINT "DocumentMetadata_resourceId_fkey" FOREIGN KEY ("resourceId") REFERENCES "Resource"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AIAnalysis" ADD CONSTRAINT "AIAnalysis_resourceId_fkey" FOREIGN KEY ("resourceId") REFERENCES "Resource"("id") ON DELETE CASCADE ON UPDATE CASCADE;
